export type SubclassDefinition = {
  id: string;
  classId: string;
  name: string;
  summary: string;
  source: string;
  access: AccessKind;
};

const subclass = (classId: string, id: string, name: string, summary: string, access: AccessKind = "official"): SubclassDefinition => ({
  id, classId, name, summary, source: access === "open" ? "SRD 5.2.1" : "Livro do Jogador 2024", access,
});

const supplementSubclass = (classId: string, id: string, name: string, summary: string, source: string): SubclassDefinition => ({
  id, classId, name, summary, source, access: "official",
});

